changeSet.sql:
CREATE OR REPLACE FUNCTION questions_search_vector_update()
RETURNS TRIGGER AS $$
BEGIN
    NEW.search_vector :=
        setweight(to_tsvector('english', coalesce(NEW.question_text, '')), 'A') ||
        setweight(to_tsvector('english', coalesce(
            regexp_replace(coalesce(NEW.answer_content, ''), E'<[^>]+>', ' ', 'g'), ''
        )), 'B');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

changeSet.rollback:
DROP TRIGGER IF EXISTS questions_search_vector_trigger ON questions;
DROP FUNCTION IF EXISTS questions_search_vector_update();
DROP INDEX IF EXISTS idx_questions_search_vector;
